// ─── File: FullFlowDemo.java ───
// Simulates the full request flow in ONE runnable file.
// Each class below would live in its own file in a real project.
package com.bank.flow;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class FullFlowDemo {

    private static final Logger log = Logger.getLogger("Flow");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Edge: gateway authenticates, rate-limits, routes.
        ApiGateway gateway = new ApiGateway();
        ServiceRegistry registry = new ServiceRegistry();
        registry.register("transfer-service", "10.0.0.11:8080");
        registry.register("transfer-service", "10.0.0.12:8080");  // two live instances

        AccountsClient accounts = new AccountsClient();            // inter-service dependency
        TransferService transfer = new TransferService(accounts);
        gateway.wire(registry, transfer);

        // A single customer request enters the system.
        Map<String, String> headers = new HashMap<>();
        headers.put("Authorization", "Bearer valid-jwt-for-rajesh");
        gateway.handleTransfer(headers, "SAV2001", "CUR3001", new BigDecimal("50000"));
    }
}

// ─── gateway/ApiGateway.java ───
class ApiGateway {
    private static final Logger log = Logger.getLogger("Flow");
    private ServiceRegistry registry;
    private TransferService transfer;

    void wire(ServiceRegistry registry, TransferService transfer) {
        this.registry = registry; this.transfer = transfer;
    }

    void handleTransfer(Map<String, String> headers, String from, String to, BigDecimal amount) {
        String traceId = TraceContext.newTrace();                 // tag the whole journey
        log.info(() -> "[" + traceId + "] GATEWAY received POST /api/v1/transfers");

        if (!headers.getOrDefault("Authorization", "").startsWith("Bearer valid")) {
            log.severe(() -> "[" + traceId + "] GATEWAY auth failed → 401");
            return;
        }
        log.info(() -> "[" + traceId + "] GATEWAY auth OK, rate-limit OK");

        // service discovery: resolve a live instance by logical name
        String instance = registry.resolve("transfer-service");
        log.info(() -> "[" + traceId + "] DISCOVERY transfer-service → " + instance);

        transfer.transfer(traceId, from, to, amount);              // route to the service
        log.info(() -> "[" + traceId + "] GATEWAY returning 201 Created to client");
    }
}

// ─── discovery/ServiceRegistry.java ───
class ServiceRegistry {
    private static final Logger log = Logger.getLogger("Flow");
    private final Map<String, List<String>> instances = new HashMap<>();
    private int rr = 0;

    void register(String name, String addr) {
        instances.computeIfAbsent(name, k -> new ArrayList<>()).add(addr);
    }
    // round-robin client-side load balancing over healthy instances
    String resolve(String name) {
        List<String> live = instances.getOrDefault(name, List.of());
        if (live.isEmpty()) throw new IllegalStateException("No instances of " + name);
        return live.get((rr++) % live.size());
    }
}

// ─── transfer/TransferService.java ───
class TransferService {
    private static final Logger log = Logger.getLogger("Flow");
    private final AccountsClient accounts;
    private final Map<String, BigDecimal> db = new HashMap<>();    // this service's OWN database

    TransferService(AccountsClient accounts) {
        this.accounts = accounts;
        db.put("SAV2001", new BigDecimal("1000000"));              // Rajesh
        db.put("CUR3001", new BigDecimal("250000"));               // Priya
    }

    void transfer(String traceId, String from, String to, BigDecimal amount) {
        // inter-service call to confirm destination exists (accounts service owns it)
        boolean exists = accounts.accountExists(traceId, to);
        if (!exists) { log.severe(() -> "[" + traceId + "] destination invalid → 400"); return; }

        BigDecimal fromBal = db.get(from);
        if (fromBal.compareTo(amount) < 0) {
            log.severe(() -> "[" + traceId + "] insufficient funds → 400"); return;
        }
        db.put(from, fromBal.subtract(amount));                    // Rajesh 1,000,000 → 950,000
        db.put(to, db.get(to).add(amount));                        // Priya  250,000 → 300,000
        log.info(() -> "[" + traceId + "] TRANSFER done " + from + "→" + to + " Rs." + amount);
        // publish "transfer.completed" event here for async audit/notification (omitted)
    }
}

// ─── accounts/AccountsClient.java ───
// Synchronous inter-service call wrapped with timeout + circuit breaker.
class AccountsClient {
    private static final Logger log = Logger.getLogger("Flow");
    private int failures = 0;
    private boolean open = false;

    boolean accountExists(String traceId, String accountId) {
        if (open) {                                                // circuit open → fail fast
            log.warning(() -> "[" + traceId + "] ACCOUNTS circuit OPEN, fail fast (fallback)");
            return true;                                           // fallback: assume valid (cached)
        }
        try {
            // simulate a remote REST/gRPC call with a timeout budget
            boolean result = callRemote(accountId);
            failures = 0;
            log.info(() -> "[" + traceId + "] ACCOUNTS exists(" + accountId + ")=" + result);
            return result;
        } catch (RuntimeException e) {
            if (++failures >= 5) { open = true; }                  // trip the breaker
            log.log(Level.SEVERE, "[" + traceId + "] ACCOUNTS call failed (" + failures + ")", e);
            return true;                                           // degrade gracefully
        }
    }
    private boolean callRemote(String accountId) { return accountId != null; }
}

// ─── trace/TraceContext.java ───
class TraceContext {
    static String newTrace() { return UUID.randomUUID().toString().substring(0, 8); }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
